def compute(vars):
    values = [vars["v1"], vars["v2"]]
    threshold = 50000
    years_exceeding = sum(1 for value in values if value > threshold)

    return {
        "value": years_exceeding,
        "trace": {
            "values": values,
            "threshold": threshold,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years"
            }
        }
    }
